NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: 'Obwohl Gott früher vielfach und vielfältig zu den Vorfahren geredet hat durch die Propheten,',
        2: 'hat er am Ende dieser Tage zu uns geredet durch [seinen] Sohn, den er als Erben aller [Dinge] eingesetzt hat [und] durch den er sogar das Universum gemacht hat.',
        3: 'Er, der die Ausstrahlung der Herrlichkeit und Ausdruck seines Wesens ist und alles durch das Wort seiner Kraft aufrechterhält, hat zur Rechten der Majestät in den Höhen Platz genommen, nachdem er die Reinigung von den Sünden [möglich] gemacht hat.',
        4: 'Er ist so viel besser geworden als die Engel, wie er einen bedeutenderen Namen geerbt hat als sie.',
        5: 'Denn zu wem von den Engeln hat er jemals gesagt: „Du bist mein Sohn, ich habe dich heute gezeugt“? Und außerdem: „Ich werde für ihn ein Vater sein, und er wird für mich ein Sohn sein.“',
        6: 'Und außerdem, sobald er den Erstgeborenen in die Welt hineingebracht hat, sagt er: „Und alle Engel Gottes sollen ihn anbeten.“',
        7: 'Und zu den Engeln sagt er: „Wer seine Engel zu Winden macht und seine Diener zu einer Feuerflamme …“,',
        8: 'aber zu dem Sohn: „Dein Thron, oh Gott, [besteht] ‹für immer und ewig›, und das Zepter der Aufrichtigkeit [ist] das Zepter deines Königreiches.',
        9: 'Du hast Gerechtigkeit geliebt und Gesetzlosigkeit gehasst; deshalb hat Gott, dein Gott, dich gesalbt mit dem Öl des Jubels, im Gegensatz zu deinen Gefährten.“',
        10: 'Und: „Du, Herr, hast zu Beginn die Erde gegründet, und die Himmel sind Werke deiner Hände;',
        11: 'sie werden vergehen, du aber bleibst, und alles wird altern wie ein Gewand,',
        12: 'und wie einen Umhang wirst du sie aufrollen, wie ein Gewand werden sie sogar gewechselt werden; du aber bist derselbe, und deine Jahre werden nicht ausgehen.“',
        13: 'Aber zu welchem der Engel hat er jemals gesagt: „Setze dich zu meiner Rechten, bis ich deine Feinde hinlege als Schemel für deine Füße“?',
        14: 'Sind sie nicht alle dienstbare Geister, zum Dienst ausgesandt um derer willen, die das Heil erben sollen?',
    },
    2: {
        1: 'Deshalb müssen wir mehr auf das Gehörte achten, sonst driften wir ab.',
        2: 'Denn wenn das durch Engel gesprochene Wort verbindlich war und jeder Fehltritt und Ungehorsam eine gerechte Strafe [zugewiesen] bekommen hat,',
        3: 'wie werden wir entrinnen, wenn wir ein derart großes Heil versäumen, welches uns gegenüber – nachdem es [seinen] Anfang genommen hat, um durch den Herrn kommuniziert zu werden – von denen bestätigt wurde, die es gehört haben,',
        4: 'während Gott mit Zeichen und Wundern und verschiedenen Kräften und Austeilungen des heiligen Geistes nach seinem Willen Zeugnis ablegt?',
        5: 'Denn nicht Engeln hat er den zukünftigen Erdkreis untergeordnet, über den wir reden.',
        6: 'Jemand hat aber irgendwo bezeugt und gesagt: „Was ist der Mensch, dass du an ihn denkst, oder der Sohn des Menschen, dass du dich um ihn kümmerst?',
        7: 'Du hast ihn kurze Zeit etwas geringer gemacht als Engel, du hast ihn mit Herrlichkeit und Ehre gekrönt.',
        8: 'Du hast alle [Dinge] unter seine Füße untergeordnet.“Denn indem er ihm alles untergeordnet hat, ließ er ihm nichts „ununtergeordnet“. Jetzt aber sehen wir noch nicht, dass ihm alles untergeordnet ist.',
        9: 'Aber bald sehen wir Jesus – der etwas geringer gemacht ist als die Engel, ‹weil er den Tod erleiden musste› – mit Herrlichkeit und Ehre gekrönt, sodass er durch Gottes Gnade für jeden den Tod geschmeckt hat.',
        10: 'Denn es gefiel ihm, um dessen willen alles und durch den alles [besteht], indem er viele Söhne zur Herrlichkeit führte, den Urheber ihres Heils durch Leiden zu vollenden.',
        11: 'Denn sowohl derjenige, der heiligt, als auch diejenigen, die geheiligt werden, [stammen] alle von dem Einen, weshalb er sich nicht schämt, sie „Geschwister“zu nennen,',
        12: 'und sagt: „Ich werde meinen Geschwistern deinen Namen verkünden; inmitten der Versammlung werde ich dich preisen.“',
        13: 'Und außerdem: „Ich werde auf dich vertrauen.“Und außerdem: „Siehe!, ich und die Kinder, die Gott mir gegeben hat.“',
        14: 'Weil also die Kinder am Blut und Fleisch teilhaben, hat auch er selbst sich gleichermaßen an ihnen beteiligt, um durch [seinen] Tod den zu entmachten, der die Gewalt hat über den Tod (das heißt: den Teufel),',
        15: 'und all diejenigen zu befreien, die aus Furcht vor dem Tod ‹zeit ihres Lebens› der Sklaverei unterworfen waren.',
        16: 'Denn er sorgt sich mit Sicherheit nicht um Engel, sondern er sorgt sich um die Nachkommenschaft Abrahams.',
        17: 'Daher musste er in jeder Hinsicht den Geschwistern gleich werden, damit er in Bezug auf das, was Gott gegenüber [von Bedeutung ist], ein barmherziger und treuer Oberpriester wird, um die Sünden des Volkes wiedergutzumachen.',
        18: 'Denn durch das, was er selbst erlitten hat, als er versucht wurde, kann er denen helfen, die versucht werden.',
    },
    3: {
        1: 'Daher, heilige Geschwister, Teilhaber der himmlischen Berufung: Betrachtet den Gesandten und Oberpriester unseres Bekenntnisses, Jesus,',
        2: 'der dem treu ist, der ihn dazu gemacht hat, wie auch Mose in seinem gesamten Haus.',
        3: 'Denn dieser ist größerer Herrlichkeit gewürdigt worden als Mose, insofern größere Ehre als das Haus derjenige hat, der es errichtet hat.',
        4: 'Denn jedes Haus wird von jemandem errichtet, aber der alles errichtet hat, [ist] Gott.',
        5: 'Auch Mose [war] in seinem gesamten Haus treu wie ein Diener, zum Zeugnis dessen, was gesagt werden sollte,',
        6: 'Christus dagegen [steht] wie ein Sohn über seinem Haus – sein Haus sind wir, wenn wir nur an der Zuversicht und dem Rühmen der Hoffnung festhalten.',
        7: 'Darum, wie der heilige Geist sagt: „Heute, wenn ihr seine Stimme hört,',
        8: 'verhärtet eure Herzen nicht wie während der Verbitterung, am Tag der Prüfung in der Wüste,',
        9: 'wo eure Vorfahren [mich] mit einer Prüfung auf die Probe stellten und sie meine Werke sahen,',
        10: 'vierzig Jahre lang. Darum war ich dieser Generation böse, und ich sagte: ‚Jedes Mal werden sie im Herzen irregeführt, sie aber kennen meine Wege nicht,',
        11: 'wie ich in meinem Zorn geschworen habe: Wenn sie in meine Ruhe eingehen sollten …“',
        12: 'Seht zu, Geschwister, sonst wird in jemandem von euch ein böses Herz des Unglaubens sein, während er vom lebendigen Gott abfällt,',
        13: 'sondern ermahnt euch selbst täglich, solange es das „Heute“genannt wird, sodass niemand von euch durch den Betrug der Sünde verhärtet wird.',
        14: 'Denn wir sind Teilhaber des Christus geworden, wenn wir nur die ‹ursprüngliche Entscheidung› bis zum Ende standhaft festhalten,',
        15: 'während gesagt wird: „Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht wie während der Verbitterung!“',
        16: 'Denn wer hörte zu und wurde verbittert? Doch nicht alle, die durch Mose aus Ägypten ausgezogen waren?',
        17: 'Und wem war er vierzig Jahre lang böse? Nicht denen, die gesündigt hatten [und] deren Leichen in der Wildnis fielen?',
        18: 'Aber wem hat er geschworen, dass sie nicht in seine Ruhe eingehen, außer denen, die ungehorsam waren?',
        19: 'Und wir sehen, dass sie wegen [ihres] Unglaubens nicht eingehen konnten.',
    },
    4: {
        1: 'Lasst uns also – da die Verheißung, in seine Ruhe einzugehen, aussteht – ehrfürchtig sein, damit niemand von euch den Eindruck macht, sie verpasst zu haben.',
        2: 'Denn uns ist ja die gute Nachricht genauso verkündet worden wie jenen auch; doch das Wort der Kunde hat jenen nichts genutzt, da sie nicht mit denen im Glauben vereint waren, die es [jetzt] hören.',
        3: 'Wir, die wir glauben, gehen nämlich in [seine] Ruhe ein, wie er gesagt hat: „Wie ich in meinem Zorn geschworen habe: Wenn sie in meine Ruhe eingehen sollten …“, obwohl die Werke seit Grundlegung der Welt erbracht sind.',
        4: 'Denn irgendwo hat er über den siebten [Tag] folgendermaßen gesprochen: „Da ruhte Gott am siebten Tag von allen seinen Werken“,',
        5: 'und doch [sagt er] an dieser [Stelle] außerdem: „Wenn sie in meine Ruhe eingehen sollten …“',
        6: 'Da also einige übrig sind, um darin einzugehen, und die, denen die gute Nachricht früher verkündet wurde, sind wegen [ihres] Ungehorsams nicht eingegangen,',
        7: 'deshalb legt er wieder einen bestimmten Tag fest, ein „Heute“, indem er nach so langer Zeit durch David sagt (wie er zuvor gesagt hat): „Heute, wenn ihr seine Stimme hört, verhärtet eure Herzen nicht!“',
        8: 'Denn wenn Josua sie zur Ruhe gebracht hätte, dann hätte er danach nicht über einen anderen Tag gesprochen.',
        9: 'Also bleibt dem Volk Gottes eine Sabbatruhe übrig.',
        10: 'Denn wer in seine Ruhe eingegangen ist, kommt auch selbst zur Ruhe von seinen Werken, genau wie Gott von den seinen.',
        11: 'Lasst uns also alles daransetzen, in jene Ruhe einzugehen, damit niemand in dasselbe Muster des Ungehorsams verfällt.',
        12: 'Denn das Wort Gottes [ist] lebendig und wirksam und schärfer als jedes zweischneidige Schwert und dringt durch bis zur Bindestelle von Seele und Geist, von Mark und Bein, und [es ist] ein Richter der Erwägungen und Einsichten des Herzens.',
        13: 'Und kein Geschöpf ist vor ihm unsichtbar, sondern alles [ist] nackt und entblößt vor den Augen dessen, gegenüber dem wir ‹Rechenschaft abzulegen haben›.',
        14: 'Da wir also einen großen Oberpriester haben, der die Himmel durchschritten hat – Jesus, den Sohn Gottes –, deshalb lasst uns an dem Bekenntnis festhalten.',
        15: 'Wir haben nämlich keinen Oberpriester, der unsere Schwachheiten nicht nachempfinden kann, sondern der in jeder Hinsicht auf gleiche Weise versucht worden ist, [jedoch] ohne Sünde.',
        16: 'Lasst uns also mit Zuversicht an den Thron der Gnade herantreten, damit wir Barmherzigkeit empfangen und Gnade finden für [seine] rechtzeitige Hilfe.',
    },
    5: {
        1: 'Denn jeder Oberpriester, der von Menschen genommen wird, wird [als Stellvertreter] für Menschen eingesetzt, ‹was das Verhältnis zu Gott betrifft›, damit er sowohl Gaben als auch Opfer für [deren] Sünden darbringt,',
        2: 'wobei er den Unwissenden und Irregeführten nachempfinden kann, weil auch er selbst mit Schwachheit behaftet ist,',
        3: 'und ihretwegen ist er verpflichtet, wie für das Volk, so auch für sich, [Opfer] für [seine] Sünden darzubringen.',
        4: 'Und keiner nimmt sich selbst die Ehre, sondern er wird von Gott berufen, so wie Aaron.',
        5: 'So hat auch Christus nicht sich selbst verherrlicht, um Oberpriester zu werden, sondern der zu ihm gesagt hat: „Mein Sohn bist du, ich habe dich heute gezeugt.“',
        6: 'Wie er auch an anderer [Stelle] sagt: „Du [bist] Priester in Ewigkeit, nach der Ordnung Melchisedeks.“',
        7: 'Der hat in den Tagen seines irdischen Lebens Gebete und Fürbitten mit lautem Klagen und Tränen dem dargebracht, der ihn aus dem Tod retten konnte, und ist wegen [seiner] Frömmigkeit erhört worden;',
        8: 'obwohl er [sein] Sohn war, hat er Gehorsam gelernt aus dem, was er erlitten hat.',
        9: 'Und als er vollendet worden war, ist er für alle, die ihm gehorchen, zum Urheber ewigen Heils geworden,',
        10: 'weil er von Gott als Oberpriester eingeführt wurde, nach der Ordnung Melchisedeks.',
        11: 'Darüber [hat] uns das Wort viel zu sagen, aber [es ist] schwer zu erklären, weil ihr im Zuhören träge geworden seid.',
        12: 'Denn auch wenn ihr in Anbetracht der Zeit [längst] Lehrer sein müsstet, habt ihr es wieder nötig, dass man euch lehrt, was die Eckpunkte der Aussprüche Gottes [sind], und ihr seid [Menschen] geworden, die Milch nötig haben und nicht feste Nahrung.',
        13: 'Denn jeder, der an der Milch teilhat, [ist] unerfahren am Wort der Gerechtigkeit, er ist nämlich unmündig.',
        14: 'Die feste Nahrung ist hingegen für Erwachsene, die sich aufgrund [ihrer] Reife die Fähigkeiten zur Unterscheidung von Gut und Schlecht angeeignet haben.',
    },
    6: {
        1: 'Darum lasst uns das Wort vom Anfang des Christus verlassen und zur Vollkommenheit bringen, damit wir nicht erneut ein Fundament [bestehend] aus Buße von toten Werken und Glauben an Gott legen,',
        2: 'der Lehre von den Taufen und der Handauflegung und der Auferstehung der Toten und dem ewigen Gericht.',
        3: 'Und das werden wir tun, wenn Gott es nur zulässt.',
        4: 'Denn [es ist] unmöglich, diejenigen, die einmal erleuchtet worden sind und das himmlische Geschenk geschmeckt haben und des heiligen Geistes teilhaftig geworden sind',
        5: 'und das gute Wort Gottes und die Kräfte des zukünftigen Zeitalters geschmeckt haben',
        6: 'und dann abgefallen sind, wieder zur Buße zu erneuern, da sie für sich selbst den Sohn Gottes wieder kreuzigen und zum Gespött machen.',
        7: 'Denn ein Land, das den Regen trinkt, der regelmäßig darauf kommt, und nützliches Kraut für die entstehen lässt, um deren willen es auch bebaut wird, empfängt Segen von Gott.',
        8: 'Wenn es aber Dornen und Disteln hervorbringt, dann [ist es] untauglich und einem Fluch nahe, dessen Ziel zur Verbrennung [führt].',
        9: 'Aber wir sind in Bezug auf euch überzeugt, geliebte [Geschwister], von besseren [Dingen], die auch zum Heil gehören, wenn wir auch so reden.',
        10: 'Denn Gott [ist] nicht ungerecht, euer Werk und eure Liebe zu vergessen, die ihr gegenüber seinem Namen erwiesen habt, indem ihr den Heiligen gedient habt und dient.',
        11: 'Wir möchten aber, dass jeder von euch bis ans Ende denselben Eifer demonstriert zur Gewissheit der Hoffnung,',
        12: 'damit ihr nicht träge werdet, sondern Nachahmer derer, die durch Glauben und Geduld die Verheißungen erben.',
        13: 'Denn als Gott Abraham ein Versprechen gab, schwor er bei sich selbst, weil er bei keinem Größeren zu schwören vermochte,',
        14: 'und sagte: „Gewiss, ich werde dich reichlich segnen und werde dich reichlich vermehren.“',
        15: 'Und auf diese Weise erlangte er die Verheißung: indem er Geduld hatte.',
        16: 'Menschen schwören nämlich bei dem Größeren, und der Eid zur Bestätigung [bedeutet] für sie das Ende jeglichen Einspruchs.',
        17: 'Darum hat Gott, als er den Erben der Verheißung die Unveränderlichkeit seines Willens besonders beweisen wollte, ihn mit einem Eid verbürgt,',
        18: 'sodass wir durch zwei unveränderliche Tatsachen, bei denen Gott unmöglich lügen [kann], einen starken Trost haben – wir, die wir Zuflucht darin genommen haben, die vor [uns] liegende Hoffnung zu ergreifen;',
        19: 'die haben wir als sicheren und festen Anker der Seele, der sogar in das Innere des Vorhangs hineinreicht,',
        20: 'wo Jesus als Vorläufer für uns hineingegangen und nach der Ordnung Melchisedeks ‹für immer› Oberpriester geworden ist.',
    },
    7: {
        1: 'Denn dieser Melchisedek – König von Salem, Priester des höchsten Gottes –, der Abraham begegnete, als [dieser] zurückkehrte von der Abschlachtung der Könige und ihn segnete',
        2: '[und] dem Abraham sogar ein Zehntel von allem zuteilte, [ist] zunächst (übersetzt) ein „König der Gerechtigkeit“, dann aber auch König von Salem, das heißt: ein König des Friedens,',
        3: 'ohne Vater, ohne Mutter, ohne Stammbaum, der weder ein Geburtsdatum noch ein Lebensende hat, aber dem Sohn Gottes geähnelt hat, er bleibt Priester für alle Zeiten.',
        4: 'Aber schaut, wie groß dieser [Mann] [war], dem der Stammvater Abraham sogar ein Zehntel von der Beute gab!',
        5: 'Und diejenigen von den Söhnen Levis, die die Priesterschaft erhalten, haben ein Gebot, dem Volk nach dem Gesetz den Zehnten abzufordern (das heißt: ihren Brüdern), obwohl sie aus den Lenden Abrahams hervorgegangen sind.',
        6: 'Aber einer, der nicht von ihnen abstammte, hat Abraham den Zehnten auferlegt und hat den gesegnet, der die Verheißung hatte.',
        7: 'Aber ohne jeden Zweifel wird das Geringere von dem Besseren gesegnet.',
        8: 'Und einerseits erhalten sterbliche Menschen den Zehnten, andererseits wird bezeugt, dass er lebt.',
        9: 'Ja, ‹man könnte sagen›, auch Levi, der den Zehnten erhält, ist durch Abraham der Zehnte auferlegt;',
        10: 'er war nämlich noch in der Lende [seines] Vaters, als Melchisedek ihm begegnete.',
        11: 'Wenn nun Vollkommenheit durch das levitische Priestertum bestünde (schließlich hat das Volk darunter das Gesetz erhalten), welche Notwendigkeit [gäbe es] noch, dass ein anderer Priester „nach der Ordnung Melchisedeks“aufsteht und nicht [einer] „nach der Ordnung Aarons“benannt wird?',
        12: 'Wenn nämlich das Priestertum geändert wird, dann geschieht notwendigerweise auch eine Änderung des Gesetzes.',
        13: 'Denn der, über den dies gesagt wird, gehört einem anderen Volksstamm an, von dem niemand dem Altar zugeteilt ist.',
        14: 'Denn [es ist] offensichtlich, dass unser Herr aus Juda hervorgegangen ist; zu diesem Stamm hat Mose nichts über Priester gesagt.',
        15: 'Und es ist noch weit offensichtlicher, wenn gemäß der Ähnlichkeit mit Melchisedek ein anderer Priester aufsteht,',
        16: 'der es nicht nach dem Gesetz eines fleischlichen Gebotes geworden ist, sondern nach der Kraft eines unzerstörbaren Lebens.',
        17: 'Denn es wird bezeugt: „Du [bist] Priester ‹für immer› nach der Ordnung Melchisedeks.“',
        18: 'Denn einerseits geschieht die Aufhebung eines vorhergehenden Gebotes aufgrund seiner Schwäche und Nutzlosigkeit',
        19: '(denn das Gesetz hat nichts vollkommen gemacht), andererseits die Einführung einer besseren Hoffnung, durch die wir uns Gott nähern.',
        20: 'Und in dem Maß, wie [dies] nicht ohne einen Eid [geschah] (denn sie sind ohne einen Eid Priester geworden,',
        21: 'er hingegen mit einem Eid durch den, der zu ihm sagte: „Der Herr hat geschworen, und er wird es nicht bereuen: Du [bist] Priester in Ewigkeit“),',
        22: 'so viel mehr ist Jesus auch der Garant eines besseren Bundes geworden.',
        23: 'Und sie sind zu mehreren Priester geworden, weil sie durch den Tod daran gehindert wurden, [am Leben] zu bleiben,',
        24: 'er hingegen, weil er in Ewigkeit bleibt, behält die Priesterschaft ohne Übergabe;',
        25: 'daher kann er diejenigen vollständig retten, die sich durch ihn Gott nähern, da er immer lebt, um für sie einzutreten.',
        26: 'Denn ein solcher Oberpriester steht uns auch an: heilig, unschuldig, unbefleckt, abgesondert von den Sündern und höher als die Himmel geworden,',
        27: 'der es nicht täglich nötig hat (wie die Oberpriester), zuerst für die eigenen Sünden Opfer darzubringen, dann für die des Volkes; das hat er nämlich ein für alle Mal getan, als er sich selbst darbrachte.',
        28: 'Denn das Gesetz setzt Menschen als Oberpriester ein, die Schwachheit haben, aber das Wort des Eides, der [in der Zeit] nach dem Gesetz [erfolgte], den Sohn, der in Ewigkeit vollendet ist.',
    },
    8: {
        1: 'Aber die Hauptsache in dem Gesagten [ist]: Wir haben einen solchen Oberpriester, der zur Rechten des majestätischen Thrones in den Himmeln Platz genommen hat,',
        2: 'ein Diener des Heiligtums und des wahrhaftigen Zeltes, das der Herr errichtet hat, nicht ein Mensch.',
        3: 'Denn jeder Oberpriester wird eingesetzt, um Gaben und Opfer darzubringen; daher [war es] notwendig, dass auch dieser etwas hat, was er darbringt.',
        4: 'Wenn also er auf der Erde wäre, dann wäre er auch kein Priester, weil es diejenigen gibt, die die Gaben nach dem Gesetz darbringen',
        5: '(welche einem Hinweis und Schatten der himmlischen [Dinge] dienen, wie Mose gewarnt wurde, als er im Begriff stand, das Zelt fertigzustellen; denn er sagt: „Sieh zu, dass du alles nach dem Vorbild herstellst, das dir auf dem Berg gezeigt wurde“.',
        6: 'Aber jetzt hat er einen bedeutenderen Dienst erlangt, so viel ist er auch Mittler eines besseren Bundes, welcher auf einer besseren Verheißung beruht.',
        7: 'Denn wenn jener erste [Bund] fehlerlos wäre, dann würde man nicht Platz für einen zweiten suchen.',
        8: 'Denn er tadelt sie und sagt: „Siehe!, es kommen Tage, spricht der Herr, da werde ich mit dem Haus von Israel und mit dem Haus von Juda einen neuen Bund schließen,',
        9: '[allerdings] nicht nach der Art des Bundes, den ich mit ihren Vorfahren gemacht habe an dem Tag, als ich ihre Hand ergriff, um sie aus Ägypten herauszuführen, weil sie nicht in meinem Bund geblieben sind und ich sie preisgegeben habe, spricht der Herr.',
        10: 'Dies [ist] der Bund, den ich für das Haus von Israel einrichten werde nach jenen Tagen, spricht der Herr: Ich werde meine Gesetze in ihren Verstand geben und sie auf ihre Herzen schreiben, und ich werde ihnen zum Gott sein und sie werden mir zum Volk sein.',
        11: 'Und sie lehren nicht mehr jeder seinen Mitbürger und jeder seinen Bruder und sagen: ‚Erkenne den Herrn!‘, weil alle mich kennen werden, vom Kleinsten bis zum Größten unter ihnen,',
        12: 'weil ich ihren Ungerechtigkeiten gnädig sein werde und ich nicht länger an ihre Sünden denke.“',
        13: 'Indem er von einem „neuen“[Bund] spricht, hat er den ersten für überholt erklärt; und was überholt und veraltet ist, [ist] dem Verschwinden nahe.',
    },
    9: {
        1: 'Zwar hatte nun auch der erste [Bund] gottesdienstliche Satzungen und das weltliche Heiligtum.',
        2: 'Denn es wurde ein Zelt errichtet – das vordere, in dem der Leuchter und der Tisch und ‹die Schaubrote› [waren] –, welches „Heiligtum“genannt wurde.',
        3: 'Und hinter dem zweiten Vorhang [ist] das „Heiligtum der Heiligtümer“genannte Zelt,',
        4: 'das den goldenen Altar enthält und die Bundeslade, die von allen Seiten mit Gold bedeckt ist [und] in der der goldene Krug, der das Manna enthält, und der Stab Aarons, der gesprosst hat, und die Tafeln des Bundes,',
        5: 'aber über ihr die Cherubim der Herrlichkeit, die den Sühnedeckel überschatten, worüber jetzt nicht im Detail zu sprechen ist.',
        6: 'Und weil diese [Dinge] so eingerichtet sind, gehen die Priester zwar laufend in das erste Zelt hinein und verrichten die Dienste,',
        7: 'aber in das zweite [geht] nur der Oberpriester einmal im Jahr, [und das] nicht ohne Blut, das er für sich selbst und die unwissentlichen Sünden des Volkes darbringt.',
        8: 'Damit deutete der heilige Geist an, dass der Weg zum Heiligtum nicht offenbar gemacht würde, solange das vordere Zelt noch Bestand hat.',
        9: 'Das [ist] ein Gleichnis für die gegenwärtige Zeit, wonach Gaben und Opfer dargebracht werden, die – ‹was das Gewissen anbelangt› – den nicht vollkommen machen können, der [im Tempel] dient,',
        10: '[schließlich geht es dabei] nur um Speisen und Getränke und verschiedene Waschungen, [also] Satzungen des Fleisches, die bis zu der Zeit der Richtigstellung auferlegt werden.',
        11: 'Christus aber ist als ein Oberpriester der entstandenen Güter gekommen durch das größere und vollkommenere Zelt (ein nicht mit Händen gemachtes, das heißt, nicht von dieser Schöpfung)',
        12: 'und nicht durch das Blut von Ziegenböcken und Kälbern, sondern er ist durch sein eigenes Blut ein für alle Mal in das Heiligtum hineingegangen, sodass er eine ewige Erlösung gefunden hat.',
        13: 'Denn wenn das Blut von Ziegenböcken und Stieren und die Asche einer jungen Kuh, die auf die Verunreinigten besprengt wird, zur Reinheit des Fleisches heiligt,',
        14: 'wie viel mehr wird das Blut Christi, der sich selbst durch den ewigen Geist ohne Makel Gott dargebracht hat, unser Gewissen von toten Werken reinigen, um dem lebendigen Gott [im Tempel] zu dienen!?!',
        15: 'Und deshalb ist er der Mittler eines neuen Bundes, damit die Berufenen die Verheißung des ewigen Erbes erhalten, nachdem [sein] Tod geschehen ist zur Erlösung von den Übertretungen unter dem ersten Bund.',
        16: 'Denn wo ein Testament [existiert], da [besteht] Notwendigkeit, dass der Tod des Verfassers nachgewiesen wird;',
        17: 'denn ein Testament [ist] verbindlich angesichts der Toten, weil es niemals in Kraft tritt, solange derjenige lebt, der ihn geschlossen hat.',
        18: 'Daher ist auch der erste [Bund] nicht ohne Blut eingeweiht.',
        19: 'Denn nachdem jedes Gebot entsprechend dem Gesetz durch Mose dem ganzen Volk gesagt worden war, nahm er das Blut der Kälber und der Böcke mit Wasser und roter Wolle und Ysop und besprengte sowohl das Buch selbst als auch das ganze Volk',
        20: 'und sagte: „Dies [ist] das Blut des Bundes, den Gott für euch geboten hat.“',
        21: 'Und auch das Zelt und alle Gefäße des Tempeldienstes besprengte er in gleicher Weise mit dem Blut.',
        22: 'Ja, fast alles wird nach dem Gesetz durch Blut gereinigt, und ohne Blutvergießen gibt es keine Vergebung.',
        23: '[Es besteht] also Notwendigkeit, dass die Hinweise der [Dinge] in den Himmeln mit diesen gereinigt werden, aber die himmlischen [Dinge] selbst mit besseren Opfern als diesen.',
        24: 'Denn Christus ist nicht in ein mit Händen gemachtes Heiligtum hineingegangen, eine Kopie des wahren [Heiligtums], sondern in den Himmel selbst, um jetzt vor dem Angesicht Gottes für uns zu erscheinen,',
        25: 'und [das] nicht, um sich selbst viele Male darzubringen, wie der Oberpriester Jahr für Jahr in das Heiligtum mittels fremden Blutes hineingeht,',
        26: 'weil er [sonst] seit Grundlegung der Welt viele Male hätte leiden müssen, aber jetzt ist er ein für alle Mal an der Vollendung der Zeitalter zur Entfernung der Sünde durch sein Opfer erschienen.',
        27: 'Und insofern es den Menschen bestimmt ist, einmal zu sterben, und danach ein Gericht,',
        28: 'so wird auch Christus, der einmal dargebracht wurde, um die Sünden der vielen zu tragen, denen beim zweiten Mal ohne Sünde erscheinen, die ihn zum Heil erwarten.',
    },
    10: {
        1: 'Denn das Gesetz, das einen Schatten der bevorstehenden, guten [Dinge] enthält, nicht das Ebenbild der Sachen selbst, kann niemals Jahr für Jahr mit denselben Opfern, die sie darbringen, die Herbeikommenden für immer vollkommen machen.',
        2: 'Denn hätten [ihre] Darbringungen nicht aufgehört, weil diejenigen, die [im Tempel] dienen, nicht länger ein Bewusstsein der Sünden haben, nachdem sie ein für alle Mal gereinigt sind?',
        3: 'Doch mit ihnen [entsteht] Jahr für Jahr eine Erinnerung an die Sünden;',
        4: 'das Blut von Stieren und Ziegenböcken [ist] nämlich unfähig, Sünden wegzunehmen.',
        5: 'Darum kommt er in die Welt und sagt: „Opfer und Opfergabe hast du nicht gewollt, / aber einen Leib hast du für mich vorbereitet. /',
        6: 'An Brandopfern und [Opfern] für Sünden hast du keinen Gefallen.“',
        7: 'Dann sagte er: „Siehe!, ich komme – [so] steht es in der Rolle des Buches über mich geschrieben –, um deinen Willen, oh Gott, zu tun.“',
        8: 'Weiter oben sagt er: „Opfer und Opfergabe und Brandopfer und [Opfer] für Sünden hast du nicht gewollt und keinen Gefallen“, welche gemäß dem Gesetz dargebracht werden.',
        9: 'Dann hat er gesagt: „Siehe!, ich komme, um deinen Willen zu tun.“Er hebt das Erste auf, damit das Zweite besteht.',
        10: 'Durch diesen Willen sind wir geheiligt durch die Opfergabe des Leibes von Jesus Christus ein für alle Mal.',
        11: 'Und jeder Priester steht Tag für Tag da, dient [im Tempel] und bringt dieselben, mehrfach [notwendigen] Opfer dar, welche niemals Sünden wegnehmen können.',
        12: 'Dieser aber setzte sich, nachdem er ein einziges, auf Dauer [angelegtes] Opfer für Sünden dargebracht hatte, zur Rechten Gottes,',
        13: 'wobei er fortan wartet, bis seine Feinde als Schemel seiner Füße gesetzt worden sind.',
        14: 'Denn mit einer einzigen Opfergabe hat er diejenigen, die geheiligt werden, für alle Zeiten vollkommen gemacht.',
        15: 'Und auch der heilige Geist bezeugt uns; denn nachdem er gesagt hat:',
        16: '„Dies [ist] der Bund, den ich mit ihnen beschließen werde nach jenen Tagen, spricht der Herr: Ich gebe mein Gesetz auf ihre Herzen und auf ihren Verstand schreibe ich es ihnen.“',
        17: 'Und: „Ihre Sünden und ihre Gesetzlosigkeit werde ich gewiss nicht länger erinnern.“',
        18: 'Aber wo Vergebung von diesen [Dingen] [ist], da [braucht es] nicht länger eine Opfergabe für Sünde.',
        19: 'Also, Geschwister, da wir durch das Blut von Jesus Zuversicht auf den Zugang zum Heiligtum haben,',
        20: 'den er uns als neuen und lebendigen Weg durch den Vorhang eingeweiht hat – das heißt, durch sein Fleisch –',
        21: 'und einen großen Priester über das Haus Gottes,',
        22: 'lasst uns mit wahrhaftigem Herzen herantreten in der Gewissheit des Glaubens, die Herzen besprengt vom bösen Gewissen und den Körper gewaschen mit reinem Wasser.',
        23: 'Lasst uns unbeirrt an dem Bekenntnis der Hoffnung festhalten, denn der sie verheißen hat, [ist] treu.',
        24: 'Und lasst uns darüber nachdenken, einander Ansporn zu Liebe und zu guten Werken [zu geben],',
        25: 'und unsere Versammlungen nicht verlassen, wie [es] für einige Gewohnheit [ist], sondern einander ermutigen und das, je mehr ihr den Tag nahen seht.',
        26: 'Denn wenn wir bewusst sündigen, nachdem wir die Erkenntnis der Wahrheit erhalten haben, dann bleibt nicht länger ein Opfer für Sünden übrig,',
        27: 'aber eine gewisse furchtsame Erwartung des Gerichts und Eifer des Feuers, das die Widersacher essen wird.',
        28: 'Jemand, der das Gesetz des Mose ablehnt, stirbt ohne Barmherzigkeit auf zwei oder drei Zeugen hin.',
        29: 'Eine wie viel schlimmere Strafe, meint ihr, wird derjenige werterachtet werden, der den Sohn Gottes verschmäht und das Blut des Bundes, durch das er geheiligt wurde, für unrein hält und den Geist der Gnade beleidigt?',
        30: 'Denn wir kennen den, der gesagt hat: „Mir [gehört] die Rache; ich werde vergelten.“, und außerdem: „Der Herr richtet sein Volk.“',
        31: '[Es ist] schrecklich, in die Hände des lebendigen Gottes zu fallen.',
        32: 'Und erinnert euch an die früheren Tage, in denen ihr, nachdem ihr erleuchtet worden seid, einen großen Kampf der Leiden ertragen habt:',
        33: 'Mal werdet ihr sowohl mit Beleidigungen als auch mit Bedrängnissen zur Schau gestellt; mal seid ihr Teilhaber derer, die so behandelt werden.',
        34: 'Denn ihr habt sowohl den Gefangenen nachempfunden als auch den Raub eures Besitzes mit Freude akzeptiert, da ihr wisst, dass ihr selbst einen besseren und bleibenden Besitz habt.',
        35: 'Werft also eure Zuversicht nicht weg, die eine große Belohnung hat!',
        36: 'Denn ihr habt Beharrlichkeit nötig, damit ihr, nachdem ihr den Willen Gottes getan habt, die Verheißung bekommt.',
        37: 'Denn noch „eine sehr, sehr kleine [Weile], dann wird der Kommende kommen und es nicht hinauszögern.',
        38: 'Aber mein Gerechter wird aus Glauben leben, und wenn er sich zurückzieht, dann hat meine Seele keinen Gefallen an ihm.“',
        39: 'Wir hingegen sind nicht vom Rückzug ins Verderben [bestimmt], sondern vom Glauben zum Erhalt der Seele.',
    },
    11: {
        1: 'Nun ist Glaube das Fürwahrhalten dessen, was man hofft, ein Überzeugtsein von Tatsachen, die man nicht sieht.',
        2: 'Denn durch ihn erhielten die Alten Zusagen.',
        3: 'Durch Glauben verstehen wir, dass die Zeitalter durch Gottes Wort erschaffen sind, sodass das, was man sieht, nicht aus dem entstanden ist, was sichtbar ist.',
        4: 'Durch Glauben brachte Abel Gott ein größeres Opfer dar als Kain, wodurch ihm zugesagt wurde, gerecht zu sein, da Gott angesichts seiner Gaben [diese] Zusage gab, und durch ihn spricht er weiterhin, obwohl er gestorben ist.',
        5: 'Durch Glauben wurde Enoch [in den Himmel] versetzt, um den Tod nicht zu sehen, und er wurde nicht mehr gefunden, weil Gott ihn versetzt hatte. Denn vor der „Versetzung“ist ihm zugesagt worden, Gott zu gefallen;',
        6: 'aber ohne Glauben [ist es] unmöglich, ihm zu gefallen! Denn wer sich Gott nähert, muss glauben, dass er existiert und er denen, die ihn suchen, ein Belohner ist.',
        7: 'Durch Glauben baute Noah, da er vor [Dingen] gewarnt wurde, die noch nicht zu sehen waren, von Gottesfurcht bewegt eine Arche zur Rettung seines Hauses, wodurch er die Welt verurteilte, und er wurde ein Erbe der Gerechtigkeit, die ‹dem Glauben entspricht›.',
        8: 'Durch Glauben gehorchte Abraham, als er gerufen wurde, an einen Ort fortzuziehen, den er als Erbe erhalten sollte; und er zog fort, ohne zu wissen, wo er hinkommt.',
        9: 'Durch Glauben siedelte er im Land der Verheißung wie in einer Fremde und wohnte in Zelten mit Isaak und Jakob, den Miterben derselben Verheißung.',
        10: 'Denn er erwartete die Stadt, die die Fundamente hat [und] deren Baumeister und Erschaffer Gott [ist].',
        11: 'Durch Glauben erhielt auch Sara selbst, [obwohl] unfruchtbar, Kraft zur Gründung einer Nachkommenschaft, und zwar entgegen [ihrem] Lebensalter, weil sie den für treu hielt, der es verheißen hatte.',
        12: 'Darum wurden auch von einem Einzigen, und zwar einem Gestorbenen, [so viele] geboren wie die Sterne des Himmels an Menge und wie der Sand am Ufer des Meeres, der zahllos [ist].',
        13: 'Gemäß dem Glauben sind diese alle gestorben, wobei sie die Verheißungen nicht erhalten haben, sondern sie [nur] von Weitem sahen und begrüßten und bekannten, dass sie Fremde und Gäste auf der Erde sind.',
        14: 'Denn die solche [Dinge] sagen, verdeutlichen, dass sie eine Heimat suchen.',
        15: 'Und wenn sie sich an jene [Heimat] erinnern würden, aus der sie ausgezogen sind, dann hätten sie Zeit zurückzukehren.',
        16: 'Tatsächlich aber sehnen sie sich nach einer besseren (das heißt: himmlischen) [Heimat]. Darum schämt sich Gott ihnen gegenüber nicht, ihr Gott genannt zu werden; denn er hat eine Stadt für sie vorbereitet.',
        17: 'Durch Glauben hat Abraham Isaak dargebracht, als er auf die Probe gestellt wurde, und er, der die Verheißungen empfangen hatte, brachte den Einzigen dar,',
        18: 'zu dem gesagt worden war: „In Isaak wird dir eine Nachkommenschaft berufen werden“,',
        19: 'da er dachte, dass Gott fähig [ist], sogar aus den Toten aufzuerwecken, von wo er ihn auch gewissermaßen zurückbekam.',
        20: 'Durch Glauben segnete Isaak Jakob und Esau auch hinsichtlich bevorstehender Dinge.',
        21: 'Durch Glauben segnete Jakob, als er im Sterben lag, jeden der Söhne Josefs, und über die Spitze seines Stabes [gebeugt] betete er an.',
        22: 'Durch Glauben erinnerte Josef, als er starb, an den Auszug der Söhne Israels, und er gab Anweisungen hinsichtlich seiner Gebeine.',
        23: 'Durch Glauben wurde Mose, nachdem er geboren war, drei Monate lang von seinen Eltern versteckt, weil sie sahen, [dass] das Kind angenehm [war], und sie fürchteten die Anordnung des Königs nicht.',
        24: 'Durch Glauben weigerte sich Mose, als er groß geworden war, ein Sohn der Tochter Pharaos zu heißen,',
        25: 'vielmehr zog er es vor, zusammen mit dem Volk Gottes misshandelt zu werden als das zeitweise Vergnügen der Sünde zu haben,',
        26: 'da er die Schande Christi als größeren Reichtum erachtete als die Schätze Ägyptens, denn er sah auf die Belohnung.',
        27: 'Durch Glauben verließ er Ägypten und fürchtete sich nicht vor der Verärgerung des Königs; er hielt nämlich durch, als ob er den Unsichtbaren sehen würde.',
        28: 'Durch Glauben hat er das Passa und die Versprengung des Blutes gefeiert, damit der Würger der Erstgeborenen sie nicht berührt.',
        29: 'Durch Glauben durchquerten sie das Rote Meer wie trockenes Land; als die Ägypter es versuchten, wurden sie verschlungen.',
        30: 'Durch Glauben fielen die Mauern Jerichos, nachdem sie für sieben Tage umkreist worden waren.',
        31: 'Durch Glauben ging Rahab, die Prostituierte, nicht zusammen mit denen verloren, die ungehorsam waren, da sie die Kundschafter mit Frieden empfing.',
        32: 'Und was soll ich noch sagen? Denn die Zeit würde mir fehlen, von Gideon, Barak, Simson, Jiftach, David und Samuel und den Propheten zu erzählen,',
        33: 'die durch Glauben Königreiche eroberten, Gerechtigkeit bewirkten, Verheißungen erlangten, die Rachen von Löwen stopften,',
        34: 'die Kraft des Feuers löschten, der Klinge des Schwertes entkamen, aus Schwachheit befähigt wurden, im Kampf stark wurden, feindliche Lager in die Flucht schlugen.',
        35: 'Frauen erhielten ihre Toten aufgrund einer Auferstehung [zurück], andere wiederum wurden gefoltert, da sie [ihre] Freilassung nicht annahmen, um eine bessere Auferstehung zu erlangen.',
        36: 'Andere wiederum wurden von Gespött und Geißelhieben versucht, sowie von Fesseln und Gefängnis.',
        37: 'Sie wurden gesteinigt, sie wurden zersägt, sie starben durch Ermordung mit dem Schwert, sie gingen in Schafspelzen [und] in Ziegenhäuten umher, ausgemergelt, bedrängt, misshandelt.',
        38: 'Sie, derer die Welt nicht würdig war, irrten in Wüsten und Gebirgen und Höhlen und den Löchern der Erde umher.',
        39: 'Und obwohl sie alle durch den Glauben Zusagen erhielten, haben sie die Verheißung nicht bekommen,',
        40: 'da Gott etwas Besseres für uns vorgesehen hat, damit sie nicht ohne uns vollkommen werden.',
    },
    12: {
        1: 'Demzufolge lasst auch uns, da wir eine so große Wolke von Zeugen haben, die uns umgibt, allen Ballast und die raffinierte Sünde ablegen und mit Beharrlichkeit den vor uns liegenden Kampf laufen,',
        2: 'indem wir [unseren Blick] auf Jesus richten, den Urheber und Vollender des Glaubens, der in Anbetracht der vor ihm liegenden Freude das Kreuz erduldet und die Schande ignoriert hat und der zur Rechten des Thrones Gottes Platz genommen hat.',
        3: 'Denn bedenkt den, der einen solchen Widerspruch von den Sündern gegen sich selbst erduldet hat, damit ihr nicht ermüdet in eurer Seele und aufgebt!',
        4: 'Ihr habt noch nicht bis aufs Blut widerstanden, während ihr gegen die Sünde ankämpft.',
        5: 'Und ihr habt die Ermahnung vergessen, die euch als Kindern zusagt: „Mein Sohn, achte die Unterweisung des Herrn nicht gering und gib nicht auf, wenn du von ihm korrigiert wirst.',
        6: 'Denn wen der Herr liebt, den unterweist er, und er bestraft jeden Sohn, den er annimmt.“',
        7: 'Erduldet ihr etwas zur Unterweisung, [dann] behandelt euch Gott als [seine] Kinder. Denn wer [ist] ein Sohn, den [sein] Vater nicht unterweist?',
        8: 'Aber wenn ihr ohne Unterweisung wärt, an der alle [anderen] teilhaftig geworden sind, dann wärt ihr ja Bastarde und nicht Kinder.',
        9: 'Außerdem hatten wir unsere leiblichen Väter als Erzieher, und wir respektierten sie. Sollten wir uns aber nicht umso mehr dem Vater der Geister unterordnen und leben?',
        10: 'Denn sie unterwiesen uns für wenige Tage ‹nach ihrem Gutdünken›, er hingegen zu [unserem] Nutzen, damit wir an seiner Heiligkeit teilhaben.',
        11: 'Nun scheint alle Unterweisung zwar für den Moment nicht von Freude [bestimmt] zu sein, sondern von Traurigkeit, aber später zahlt sie denen, die dadurch trainiert sind, die friedfertige Frucht der Gerechtigkeit.',
        12: 'Darum „richtet die erschlafften Hände und die geschwächten Knie auf“',
        13: 'und „macht gerade Pfade für eure Füße“, damit das Lahme nicht ausgerenkt, sondern vielmehr geheilt wird.',
        14: 'Strebt nach Frieden mit allen und nach der Heiligung, ohne die niemand den Herrn sehen wird,',
        15: 'und kümmert euch darum, dass sich niemand von der Gnade Gottes ausschließt; dass keine bittere Wurzel emporwächst und Unruhe stiftet und viele durch sie befleckt werden;',
        16: 'dass niemand unmoralisch oder gottlos [ist] wie Esau, der für eine einzige Mahlzeit seine Erstgeburtsrechte aufgegeben hat.',
        17: 'Schließlich wisst ihr, dass er auch danach, als er den Segen erben wollte, verworfen wurde, denn er fand keine Gelegenheit zur Buße, obwohl er sie mit Tränen suchte.',
        18: 'Ihr seid nämlich nicht zu einem fühlbaren und brennenden Feuer gekommen und zu Dunkelheit und Finsternis und Unwetter',
        19: 'und zum Schall einer Posaune und der Stimme von Worten, von der die Zuhörer sich erbaten, dass ihnen kein [weiteres] Wort zugefügt werde,',
        20: 'denn sie ertrugen nicht, was [ihnen] befohlen wurde: „Auch wenn ein Tier den Berg berührt, dann soll es gesteinigt werden.“',
        21: 'Und das Spektakel war dermaßen furchterregend, [dass] Mose sagte: „Ich bin erschrocken und erschüttert.“',
        22: 'Doch ihr seid zu dem Berg Zion gekommen und der Stadt des lebendigen Gottes, dem himmlischen Jerusalem, und zu Zehntausenden von Engeln, zur Festgemeinschaft',
        23: 'und Gemeinde der Erstgeborenen, die in den Himmeln eingeschrieben sind, und zu Gott, dem Richter aller [Menschen], und den Geistern der Gerechten, die ans Ziel gelangt sind,',
        24: 'und zu Jesus, dem Mittler eines neuen Bundes, und dem versprengten Blut, das besser redet als [das Blut von] Abel.',
        25: 'Seht zu, dass ihr den nicht abweist, der [zu euch] redet! Denn wenn jene nicht entkamen, die den abwiesen, der auf der Erde warnte, dann umso weniger wir, die wir uns von dem abwenden, der von den Himmeln her [warnt];',
        26: 'dessen Stimme hat die Erde damals erschüttert, aber jetzt hat er versprochen und gesagt: „Noch einmal werde ich [sie] erbeben lassen, [und zwar] nicht nur die Erde, sondern auch den Himmel.',
        27: 'Aber das „noch einmal“deutet die Veränderung dessen an, was erschüttert werden kann beziehungsweise was gemacht ist, damit [unverändert] bleibt, was nicht erschüttert werden kann.',
        28: 'Darum: Weil wir ein unerschütterliches Königreich erhalten, lasst uns ‹dankbar sein›, wodurch wir Gott wohlgefällig dienen, mit Ehrfurcht und Ehrerbietung!',
        29: 'Denn unser Gott [ist] ja ein verzehrendes Feuer.',
    },
    13: {
        1: 'Die geschwisterliche Liebe soll bleiben.',
        2: 'Vernachlässigt die Gastfreundschaft nicht, denn dadurch haben einige unwissend Engel beherbergt!',
        3: 'Denkt an die Gefangenen, als ob [ihr] Mitgefangene [wärt], [und] die Misshandelten, als ob auch ihr selbst ‹in ihrer Haut steckt›!',
        4: 'Die Ehe [sei] bei allen kostbar und das Ehebett unbefleckt, denn Unzüchtige und Ehebrecher wird Gott richten.',
        5: '[Euer] Lebensstil [sei] frei von Geldliebe, begnügt euch mit dem, was vorhanden ist. Denn er selbst hat gesagt: „Ich will dich gewiss nicht verlassen und dich gewiss nicht verstoßen.“',
        6: 'Darum können wir zuversichtlich sagen: „Der Herr [ist] mein Helfer, und ich will mich nicht fürchten, / was sollte ein Mensch mir antun?“',
        7: 'Denkt an eure Leiter, die euch das Wort Gottes gesagt haben; betrachtet den Ausgang ihres Lebenswandels und ahmt ihren Glauben nach!',
        8: 'Jesus Christus [ist] derselbe, gestern und heute und bis in Ewigkeiten.',
        9: 'Lasst euch nicht durch vielfältige und merkwürdige Lehren abbringen! Denn [es ist] gut, das Herz durch Gnade zu festigen, nicht durch Speisen, von denen diejenigen, die danach leben, keinen Nutzen hatten.',
        10: 'Wir haben einen Altar, von dem [selbst] diejenigen, die in dem Zelt dienen, nicht die Erlaubnis haben zu essen.',
        11: 'Denn die Kadaver dieser Tiere, deren Blut für Sünden durch den Oberpriester im Heiligtum dargebracht wird, werden außerhalb des Lagers verbrannt.',
        12: 'Darum: Auch Jesus litt außerhalb des Tors, damit er durch sein eigenes Blut das Volk heiligt.',
        13: 'Lasst uns also zu ihm hinausgehen und außerhalb des Lagers seine Schande tragen;',
        14: 'wir haben hier nämlich keine bleibende Stadt, sondern die zukünftige suchen wir.',
        15: 'Durch ihn lasst uns also Gott kontinuierlich ein Lobopfer darbringen, das heißt: eine Frucht der Lippen, die seinen Namen bekennen.',
        16: 'Und vernachlässigt die Wohltätigkeit und Großzügigkeit nicht; denn solche Opfer gefallen Gott.',
        17: 'Gehorcht und fügt euch euren Leitern (denn sie wachen über eure Seelen als diejenigen, die [einmal] Rechenschaft ablegen werden), damit sie es mit Freude tun und [dabei] nicht stöhnen; das [wäre] nämlich unerquicklich für euch.',
        18: 'Betet für uns! Denn wir sind überzeugt, dass wir ein gutes Gewissen haben, da wir uns in allem richtig verhalten wollen.',
        19: 'Besonders aber fordere ich [euch] auf, dies zu tun, damit ich schneller zu euch zurückkommen werde.',
        20: 'Der Gott des Friedens aber, der den großen Hirten der Schafe – unseren Herrn Jesus – von den Toten heraufgeführt hat durch das Blut eines ewigen Bundes,',
        21: '[der] möge euch mit allem Guten ausstatten, um seinen Willen zu tun, indem er in uns tut, was vor ihm Gefallen findet, durch Jesus Christus, dem die Ehre [sei] ‹für immer und ewig›, amen.',
        22: 'Nun ermahne ich euch, Geschwister, ertragt das Wort der Ermahnung, denn ich habe euch ja kurz geschrieben.',
        23: 'Ihr sollt wissen, dass unser Bruder Timotheus freigelassen worden ist; falls er bald kommt, werde ich euch mit ihm besuchen.',
        24: 'Grüßt alle eure Leiter und alle Heiligen! Es grüßen euch diejenigen aus Italia.',
        25: 'Die Gnade [sei] mit euch allen!',
    },
}
